package main

import "fmt"

func countdown(n int) []int {
	numbers := []int{}
	for n > 0 {
		numbers = append(numbers, n)
		n--
	}
	return numbers
}

func main() {
	var n int
	fmt.Scan(&n)
	for _, number := range countdown(n) {
		fmt.Println(number)
	}
	fmt.Println("Liftoff!")
}
